/**
 * The server's environment, read where a server can read it.
 *
 * `src/env.ts` was generated by the scaffold and **imported by nothing**, so no variable was
 * validated at runtime. Two facts constrain how it gets wired, both measured and recorded in
 * `NOTES.md` §5(d) rather than rediscovered here:
 *
 * 1. `import.meta.env` only sees variables Vite exposes. A server-only variable read that way
 *    comes back `undefined` even when it is exported into the process — `NOTES.md` measured
 *    exactly that with `SERVER_URL`. The session secret is server-only, so the runtime
 *    environment must include `process.env`.
 * 2. The scaffold declared both variables `.optional()`, which is why it builds with no
 *    `.env` at all. The session secret must not be optional, or the app starts and fails on
 *    the first request instead of at boot.
 *
 * This module is server-only. It is imported by `src/server/principal.ts` and by nothing
 * under `src/routes` or `src/components`.
 */

/** The shortest secret this will accept. Below this a cookie signature is guessable. */
const MIN_SECRET_LENGTH = 32;

/**
 * The environment this process actually has, server variables included.
 *
 * `process.env` second and therefore winning: on the server the process environment is the
 * authority, and Vite's object is a build-time snapshot that cannot see a server-only
 * variable. Spreading in this order means a value present in both resolves to the process's.
 */
export const runtimeEnvironment = (): Record<string, string | undefined> => ({
	...(import.meta.env as Record<string, string | undefined>),
	...process.env,
});

/**
 * The session secret, or a failure naming the variable.
 *
 * The message names `SESSION_SECRET` and says how to make one, because a boot failure that
 * does not say what is missing costs an operator the same half hour as no check at all.
 */
export const requireSessionSecret = (
	source: Record<string, string | undefined> = runtimeEnvironment(),
): string => {
	const secret = source.SESSION_SECRET;
	if (secret === undefined || secret.trim() === "") {
		throw new Error(
			"SESSION_SECRET is required and is not set. Relayboard signs its session cookie with it, so the app cannot serve a request without one. Set SESSION_SECRET in the environment — see .env.example — and start again.",
		);
	}
	if (secret.length < MIN_SECRET_LENGTH) {
		throw new Error(
			`SESSION_SECRET is too short (${secret.length} characters, ${MIN_SECRET_LENGTH} required). It signs the session cookie, so it needs real entropy rather than a memorable phrase; generate one with: openssl rand -base64 32`,
		);
	}
	return secret;
};
